from itertools import permutations

students = ["L", "M", "O", "R", "T", "Y"]
years = [1921, 1922, 1923, 1924]

def valid(assign):
    # assign: dict year -> student
    pos = {s: y for y, s in assign.items()}
    if assign[1923] not in ("L", "T"):
        return False
    if "M" in pos and pos["M"] not in (1921, 1922):
        return False
    if "T" in pos and "R" not in pos:
        return False
    if "R" in pos:
        if "O" not in pos or pos["O"] != pos["R"] - 1:
            return False
    return True

sols = []
for p in permutations(students, 4):
    a = dict(zip(years, p))
    if "Y" in p:
        continue
    if valid(a):
        sols.append(a)

print("Number of valid arrangements with Y excluded:", len(sols))

def inproj(a, s):
    return s in a.values()

def pos(a, s):
    for y, x in a.items():
        if x == s:
            return y
    return None

opts = {
    "A": lambda a: not inproj(a, "L"),
    "B": lambda a: not inproj(a, "R"),
    "C": lambda a: not inproj(a, "T"),
    "D": lambda a: pos(a, "O") == 1922,
    "E": lambda a: pos(a, "L") == 1924,
}

could = {}
for k, f in opts.items():
    wit = next((a for a in sols if f(a)), None)
    could[k] = wit
    print(k, "could be true:", wit is not None, wit)

true_opts = [k for k, w in could.items() if w is not None]
print("Options that could be true:", true_opts)

claimed = "A"
if true_opts == [claimed]:
    print("CHECK PASS")
else:
    print("CHECK FAIL: claimed", claimed, "but correct set is", true_opts)
